Get-ChildItem scripts -Recurse -File -Filter '*.sh' | ForEach-Object {
  $t = [IO.File]::ReadAllText($_.FullName)
  if (-not $t.StartsWith('#!')) { [IO.File]::WriteAllText($_.FullName, "#!/usr/bin/env bash`n" + $t) }
}

